    '\nCREATE TABLE ngapact (\n\tid INTEGER NOT NULL, \n\tdossier_id INTEGER NOT NULL, \n\tmouvement_id INTEGER, \n\tintervention_id INTEGER, \n\tidentifiant_acte VARCHAR, \n\tlettre_cle VARCHAR NOT NULL, \n\tcoefficient FLOAT NOT NULL, \n\tdenombrement INTEGER, \n\tquantite INTEGER, \n\tposition_dentaire VARCHAR, \n\texecute_date DATETIME NOT NULL, \n\tnumero_seance INTEGER, \n\tnabm_codes VARCHAR, \n\tmajoration_pourcentage INTEGER, \n\tmajoration_coefficient FLOAT, \n\tminoration_pourcentage INTEGER, \n\tminoration_coefficient FLOAT, \n\trisque VARCHAR, \n\tentente_prealable VARCHAR, \n\tindicateur_parcours_soins VARCHAR, \n\tdate_demande_accord DATE, \n\tmontant_total FLOAT, \n\tmontant_depassement FLOAT, \n\tmotif_depassement VARCHAR, \n\tnumero_facture VARCHAR, \n\tbhn_phn_montant FLOAT, \n\tcommentaire VARCHAR, \n\taction VARCHAR NOT NULL, \n\tfacturable BOOLEAN NOT NULL, \n\texecution_nuit BOOLEAN NOT NULL, \n\texecution_dimanche_ferie BOOLEAN NOT NULL, \n\tacte_hors_nomenclature BOOLEAN NOT NULL, \n\trapport_exoneration VARCHAR, \n\tgratuit BOOLEAN NOT NULL, \n\tvalide BOOLEAN NOT NULL, \n\tfacture BOOLEAN NOT NULL, \n\tportee_cle VARCHAR NOT NULL, \n\tactivite_recherche BOOLEAN NOT NULL, \n\tcode_prestation VARCHAR, \n\tprestataire_id INTEGER, \n\tdate_action DATETIME, \n\tacteur_id INTEGER, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(dossier_id) REFERENCES dossier (id), \n\tFOREIGN KEY(mouvement_id) REFERENCES mouvement (id), \n\tFOREIGN KEY(intervention_id) REFERENCES intervention (id), \n\tFOREIGN KEY(prestataire_id) REFERENCES medecinresponsable (id)\n)\n\n',
    '\nCREATE TABLE ucdact (\n\tid INTEGER NOT NULL, \n\tdossier_id INTEGER NOT NULL, \n\tmouvement_id INTEGER, \n\tintervention_id INTEGER, \n\tidentifiant_acte VARCHAR, \n\tcode_interne_ucd VARCHAR, \n\tcode_ucd VARCHAR NOT NULL, \n\tcode_commercial VARCHAR, \n\tdenomination_libelle VARCHAR, \n\tdenomination_dosage VARCHAR, \n\tdenomination_forme VARCHAR, \n\texecute_date DATETIME NOT NULL, \n\tnature_date VARCHAR, \n\tquantite FLOAT NOT NULL, \n\ttaux_tva FLOAT, \n\tmontant_unitaire_achat_ttc FLOAT, \n\tmontant_unitaire_achat_ht FLOAT, \n\tmontant_ecart_indemnisable FLOAT, \n\tmontant_unitaire_facture_ttc FLOAT, \n\tmontant_unitaire_facture_ht FLOAT, \n\tmontant_marge_retrocession FLOAT, \n\tmontant_reconstitution FLOAT, \n\trisque VARCHAR, \n\tentente_prealable VARCHAR, \n\tindicateur_parcours_soins VARCHAR, \n\tdate_demande_accord DATE, \n\tnature_prestation VARCHAR, \n\tsiret_fournisseur VARCHAR, \n\tnumero_lot VARCHAR, \n\tcode_indication_les VARCHAR, \n\tcommentaire VARCHAR, \n\taction VARCHAR NOT NULL, \n\tfacturable BOOLEAN NOT NULL, \n\tgratuit BOOLEAN NOT NULL, \n\tvalide BOOLEAN NOT NULL, \n\tfacture BOOLEAN NOT NULL, \n\tliberal BOOLEAN NOT NULL, \n\tretrocession BOOLEAN NOT NULL, \n\tessai_therapeutique BOOLEAN NOT NULL, \n\tprescripteur_id INTEGER, \n\tprestataire_id INTEGER, \n\tdate_action DATETIME, \n\tacteur_id INTEGER, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(dossier_id) REFERENCES dossier (id), \n\tFOREIGN KEY(mouvement_id) REFERENCES mouvement (id), \n\tFOREIGN KEY(intervention_id) REFERENCES intervention (id), \n\tFOREIGN KEY(prescripteur_id) REFERENCES medecinresponsable (id), \n\tFOREIGN KEY(prestataire_id) REFERENCES medecinresponsable (id)\n)\n\n',
    '\nCREATE TABLE venue_contact (\n\tid INTEGER NOT NULL, \n\tvenue_id INTEGER NOT NULL, \n\tsequence INTEGER NOT NULL, \n\tfamily_name VARCHAR(100) NOT NULL, \n\tgiven_name VARCHAR(100), \n\tmiddle_name VARCHAR(100), \n\tprefix VARCHAR(20), \n\tsuffix VARCHAR(20), \n\trelationship_code VARCHAR(20) NOT NULL, \n\trelationship_display VARCHAR(100), \n\trelationship_system VARCHAR(50), \n\taddress_line1 VARCHAR(200), \n\taddress_line2 VARCHAR(200), \n\taddress_city VARCHAR(100), \n\taddress_postalcode VARCHAR(20), \n\taddress_country VARCHAR(3), \n\tphone_number VARCHAR(50), \n\tphone_use VARCHAR(20), \n\tbusiness_phone VARCHAR(50), \n\tcontact_role VARCHAR(50), \n\tstart_datetime DATETIME, \n\tend_datetime DATETIME, \n\tgender VARCHAR(1), \n\tbirth_date DATE, \n\tcontact_reason VARCHAR(200), \n\tis_accompanying BOOLEAN NOT NULL, \n\tcan_visit BOOLEAN NOT NULL, \n\tnotification_required BOOLEAN NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(venue_id) REFERENCES venue (id)\n)\n\n',
    '\nCREATE TABLE vocabularysystem (\n\tid INTEGER NOT NULL, \n\tname VARCHAR NOT NULL, \n\tlabel VARCHAR NOT NULL, \n\turi VARCHAR, \n\toid VARCHAR, \n\tdescription VARCHAR, \n\tsystem_type VARCHAR(5) NOT NULL, \n\tis_user_defined BOOLEAN NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME, \n\tPRIMARY KEY (id)\n)\n\n',
    '\nCREATE TABLE vocabularyvalue (\n\tid INTEGER NOT NULL, \n\tsystem_id INTEGER NOT NULL, \n\tcode VARCHAR NOT NULL, \n\tdisplay VARCHAR NOT NULL, \n\tdefinition VARCHAR, \n\tis_active BOOLEAN NOT NULL, \n\t"order" INTEGER NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(system_id) REFERENCES vocabularysystem (id)\n)\n\n',
    '\nCREATE TABLE vocabularymapping (\n\tid INTEGER NOT NULL, \n\tsource_value_id INTEGER NOT NULL, \n\ttarget_system_id INTEGER NOT NULL, \n\ttarget_code VARCHAR NOT NULL, \n\tmap_type VARCHAR NOT NULL, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(source_value_id) REFERENCES vocabularyvalue (id), \n\tFOREIGN KEY(target_system_id) REFERENCES vocabularysystem (id)\n)\n\n',
    '\nCREATE TABLE workflow_scenarios (\n\tid INTEGER NOT NULL, \n\tname VARCHAR(200) NOT NULL, \n\tdescription TEXT, \n\tscenario_type VARCHAR(24) NOT NULL, \n\tght_context_id INTEGER, \n\tis_active BOOLEAN NOT NULL, \n\tcategory VARCHAR(100), \n\ttags JSON, \n\tsource_scenario_id INTEGER, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(ght_context_id) REFERENCES ghtcontext (id)\n)\n\n',
    '\nCREATE TABLE workflow_scenario_executions (\n\tid INTEGER NOT NULL, \n\tscenario_id INTEGER NOT NULL, \n\tght_context_id INTEGER, \n\tpatient_id INTEGER, \n\tdossier_id INTEGER, \n\tstatus VARCHAR(10) NOT NULL, \n\terror_message TEXT, \n\tstarted_at DATETIME, \n\tcompleted_at DATETIME, \n\temit_hl7 BOOLEAN NOT NULL, \n\temit_fhir BOOLEAN NOT NULL, \n\thl7_endpoint_id INTEGER, \n\tfhir_endpoint_id INTEGER, \n\texecution_context JSON, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(scenario_id) REFERENCES workflow_scenarios (id), \n\tFOREIGN KEY(ght_context_id) REFERENCES ghtcontext (id), \n\tFOREIGN KEY(patient_id) REFERENCES patient (id), \n\tFOREIGN KEY(dossier_id) REFERENCES dossier (id), \n\tFOREIGN KEY(hl7_endpoint_id) REFERENCES systemendpoint (id), \n\tFOREIGN KEY(fhir_endpoint_id) REFERENCES systemendpoint (id)\n)\n\n',
    '\nCREATE TABLE workflow_scenario_steps (\n\tid INTEGER NOT NULL, \n\tscenario_id INTEGER NOT NULL, \n\torder_index INTEGER NOT NULL, \n\taction_type VARCHAR(21) NOT NULL, \n\tname VARCHAR(200), \n\tdescription TEXT, \n\tparameters JSON, \n\tdelay_seconds INTEGER NOT NULL, \n\temit_hl7 BOOLEAN NOT NULL, \n\temit_fhir BOOLEAN NOT NULL, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(scenario_id) REFERENCES workflow_scenarios (id)\n)\n\n',
    '\nCREATE TABLE workflow_execution_steps (\n\tid INTEGER NOT NULL, \n\texecution_id INTEGER NOT NULL, \n\tstep_id INTEGER NOT NULL, \n\texecution_order INTEGER NOT NULL, \n\tentity_type VARCHAR(14), \n\tentity_id INTEGER, \n\thl7_message_id INTEGER, \n\tfhir_message_id INTEGER, \n\tstatus VARCHAR(10) NOT NULL, \n\terror_message TEXT, \n\tstarted_at DATETIME, \n\tcompleted_at DATETIME, \n\tstep_data JSON, \n\tPRIMARY KEY (id), \n\tFOREIGN KEY(execution_id) REFERENCES workflow_scenario_executions (id), \n\tFOREIGN KEY(step_id) REFERENCES workflow_scenario_steps (id), \n\tFOREIGN KEY(hl7_message_id) REFERENCES messagelog (id), \n\tFOREIGN KEY(fhir_message_id) REFERENCES messagelog (id)\n)\n\n',
    '\nCREATE TABLE outboundmessage (\n\tid INTEGER NOT NULL, \n\tendpoint_id INTEGER NOT NULL, \n\tsource_message_log_id INTEGER, \n\tscenario_delivery_id INTEGER, \n\tprotocol VARCHAR NOT NULL, \n\tmessage_type VARCHAR, \n\tcorrelation_id VARCHAR, \n\tpayload VARCHAR NOT NULL, \n\tstatus VARCHAR NOT NULL, \n\tattempts INTEGER NOT NULL, \n\tmax_attempts INTEGER NOT NULL, \n\tnext_attempt_at DATETIME NOT NULL, \n\tlast_error VARCHAR, \n\tresponse_payload VARCHAR, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tsent_at DATETIME, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_outboundmessage_scenario_delivery UNIQUE (scenario_delivery_id), \n\tFOREIGN KEY(endpoint_id) REFERENCES systemendpoint (id), \n\tFOREIGN KEY(source_message_log_id) REFERENCES messagelog (id), \n\tFOREIGN KEY(scenario_delivery_id) REFERENCES scenariodelivery (id)\n)\n\n',
    '\nCREATE TABLE scenariodelivery (\n\tid INTEGER NOT NULL, \n\tplay_id INTEGER NOT NULL, \n\tplay_step_id INTEGER NOT NULL, \n\tendpoint_id INTEGER NOT NULL, \n\tstatus VARCHAR NOT NULL, \n\ttransport VARCHAR, \n\tis_required BOOLEAN NOT NULL, \n\tscheduled_at DATETIME, \n\tvalidation_status VARCHAR, \n\tvalidation_json VARCHAR, \n\tack_code VARCHAR, \n\tresponse_payload VARCHAR, \n\terror_message VARCHAR, \n\tmessage_log_id INTEGER, \n\toutbox_id INTEGER, \n\tcompiled_payload VARCHAR, \n\ttarget_context_json VARCHAR, \n\tstarted_at DATETIME, \n\tfinished_at DATETIME, \n\tcreated_at DATETIME NOT NULL, \n\tupdated_at DATETIME NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_scenario_delivery_step_endpoint UNIQUE (play_step_id, endpoint_id), \n\tFOREIGN KEY(play_id) REFERENCES scenarioplay (id), \n\tFOREIGN KEY(play_step_id) REFERENCES scenarioplaystep (id), \n\tFOREIGN KEY(endpoint_id) REFERENCES systemendpoint (id), \n\tFOREIGN KEY(message_log_id) REFERENCES messagelog (id), \n\tFOREIGN KEY(outbox_id) REFERENCES outboundmessage (id)\n)\n\n',
