_DDL_BY_DIALECT = {'sqlite': SQLITE_DDL, 'postgresql': POSTGRESQL_DDL}

def create_head_schema(connection: Connection) -> None:
    """Crée le schéma head depuis la baseline DDL figée et versionnée."""
    statements = _DDL_BY_DIALECT.get(connection.dialect.name)
    if statements is None:
        raise RuntimeError(f'Baseline DDL indisponible pour {connection.dialect.name}')
    for statement in statements:
        connection.exec_driver_sql(statement)
